// Legacy guide topic links resolve to full static articles.
(()=>{if(!/\/guide(?:\.html)?$/.test(location.pathname))return;const routes={mileage:'guide-mileage.html',finance:'guide-finance.html',inspection:'guide-inspection.html'};const key=new URLSearchParams(location.search).get('topic');if(Object.prototype.hasOwnProperty.call(routes,key))location.replace(routes[key]);})();
const menu=document.querySelector('.menu-toggle');const nav=document.querySelector('#main-nav');function closeMenu(restoreFocus=false){const wasOpen=menu?.getAttribute('aria-expanded')==='true';menu?.setAttribute('aria-expanded','false');menu?.setAttribute('aria-label','Open menu');nav?.classList.remove('open');if(restoreFocus&&wasOpen)menu.focus()}menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close menu':'Open menu');nav.classList.toggle('open',open)});nav?.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu(true)});
const readings=[['8 Jul 2021','Service record','13,000 km'],['8 Jul 2022','Service record','26,000 km'],['8 Jul 2023','Service record','39,000 km'],['8 Jul 2024','Service record','50,000 km'],['8 Jul 2025','Service record','61,000 km'],['8 Jul 2026','Service record','72,000 km'],['20 Nov 2026','Seller declaration · needs verification','58,000 km']];document.querySelectorAll('[data-mileage]').forEach(chart=>{chart.querySelectorAll('[data-reading]').forEach(button=>button.addEventListener('click',()=>{chart.querySelectorAll('[data-reading]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));const row=readings[Number(button.dataset.reading)];chart.querySelector('.chart-readout').replaceChildren(document.createTextNode(row[0]+' · '+row[1]+' · '),Object.assign(document.createElement('strong'),{textContent:row[2]}));const circles=chart.querySelectorAll('circle');circles.forEach((c,i)=>c.setAttribute('r',String(i===Number(button.dataset.reading)?8:i===6?6:5))) }))});document.querySelector('.print-button')?.addEventListener('click',()=>window.print());
if(document.querySelector('#guide-content:not([data-guide-ready])')){fetch('guides.json').then(r=>{if(!r.ok)throw Error('Guide unavailable');return r.json()}).then(guides=>{const key=new URLSearchParams(location.search).get('topic')||'mileage';const resolved=Object.prototype.hasOwnProperty.call(guides,key)?key:'mileage';const guide=guides[resolved];const destinations={mileage:['sample.html#mileage','View sample mileage'],finance:['sample.html#finance','View sample lender entry'],inspection:['sample.html','View sample report']};const action=document.querySelector('.guide-page > .button');if(action){action.href=destinations[resolved][0];action.textContent=destinations[resolved][1]}const el=document.querySelector('#guide-content');el.replaceChildren();document.title='VIB — '+guide[0];const h=document.createElement('h1');h.textContent=guide[0];const p=document.createElement('p');p.textContent=guide[1];const img=Object.assign(document.createElement('img'),{src:'assets/'+guide[2],alt:'VIB vehicle records illustration',className:'guide-illustration'});el.append(h,p,img);guide[3].forEach(([title,copy])=>{const h=document.createElement('h2');h.textContent=title;const p=document.createElement('p');p.textContent=copy;el.append(h,p)})}).catch(()=>{document.title='VIB — Buyer guides'})}

// V4 evidence explorer: keyboard and touch share the same state.
(() => {
 const tabs=[...document.querySelectorAll('.sample-switch')]; if(!tabs.length)return;
 const list=tabs[0].closest('[role=tablist]'); const panels=tabs.map(t=>document.getElementById(t.getAttribute('aria-controls')));
 function select(tab,focus=false){tabs.forEach((t,i)=>{const on=t===tab;t.setAttribute('aria-selected',String(on));t.tabIndex=on?0:-1;panels[i].hidden=!on});if(focus)tab.focus({preventScroll:true});document.dispatchEvent(new CustomEvent('vib:report-change',{detail:{panel:document.getElementById(tab.getAttribute('aria-controls'))}}))}
 tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>select(tab));tab.addEventListener('keydown',e=>{const vertical=list.getAttribute('aria-orientation')==='vertical';let next=null;if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;else if(e.key===(vertical?'ArrowDown':'ArrowRight'))next=(i+1)%tabs.length;else if(e.key===(vertical?'ArrowUp':'ArrowLeft'))next=(i-1+tabs.length)%tabs.length;if(next!==null){e.preventDefault();select(tabs[next],true)}})});
 const mq=matchMedia('(min-width:900px)');const orient=()=>list.setAttribute('aria-orientation',mq.matches?'vertical':'horizontal');orient();mq.addEventListener('change',orient);select(tabs[0]);
})();

// The compact native report index reveals every section on a phone.
document.querySelector('.report-jump')?.addEventListener('click',event=>{if(event.target.closest('a'))event.currentTarget.open=false});

// One finding connects the homepage process.
(()=>{if(!document.querySelector('.process-steps'))return;const data=[['01 / THE FINDING','The readings conflict.','Read each value with its source and date. Neither value explains the difference on its own.','b39dc.webp','Open vehicle record illustration'],['02 / THE DOCUMENT','Ask for the original.','Compare the service document, odometer and seller’s explanation. The difference alone does not prove tampering.','1b4dc.webp','Registration document illustration'],['03 / THE CAR TODAY','History meets inspection.','Use the records with a physical inspection and test drive. Records do not assess today’s condition.','d1a82.webp','Vehicle inspection illustration']];document.querySelectorAll('.step').forEach((b,i)=>b.onclick=()=>{document.querySelectorAll('.step').forEach((e,j)=>{e.classList.toggle('selected',i===j);e.setAttribute('aria-pressed',i===j);e.querySelector('b').textContent=i===j?'−':'+'});document.querySelector('.desk-number').textContent='0'+(i+1);document.querySelector('#desk-label').textContent=data[i][0];document.querySelector('#desk-title').textContent=data[i][1];document.querySelector('#desk-caption').textContent=data[i][2];document.querySelector('#desk-image').src='assets/'+data[i][3];document.querySelector('#desk-image').alt=data[i][4];document.querySelector('.native-timeline').hidden=i!==0;document.dispatchEvent(new CustomEvent('vib:process-change',{detail:{panel:document.querySelector('.desk-paper')}}));});})();
